package com.example.taskmanager;
import com.example.taskmanager.dto.*;import com.example.taskmanager.entity.*;import com.example.taskmanager.exception.ResourceNotFoundException;import com.example.taskmanager.repository.*;import com.example.taskmanager.service.TaskService;import org.junit.jupiter.api.*;import org.junit.jupiter.api.extension.ExtendWith;import org.mockito.*;import org.mockito.junit.jupiter.MockitoExtension;import java.util.*;import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;
@ExtendWith(MockitoExtension.class) class TaskServiceTest {
 @Mock TaskRepository tasks;@Mock TenantRepository tenants;@Mock UserRepository users;@InjectMocks TaskService service;
 @Test void createsTaskForTenant(){Tenant tenant=new Tenant("Acme");when(tenants.findById(1L)).thenReturn(Optional.of(tenant));when(tasks.save(any(Task.class))).thenAnswer(i->i.getArgument(0));Task t=service.create(new CreateTaskRequest("Build API","desc"),1L);assertEquals("Build API",t.getTitle());assertEquals(tenant,t.getTenant());}
 @Test void createFailsForUnknownTenant(){when(tenants.findById(9L)).thenReturn(Optional.empty());assertThrows(ResourceNotFoundException.class,()->service.create(new CreateTaskRequest("Task",null),9L));}
 @Test void assignsOnlySameTenantUser(){Tenant tenant=new Tenant("A");Task task=new Task("T","D",tenant);AppUser user=new AppUser("u@a.com","pw",Role.USER,tenant);when(tasks.findByIdAndTenant_Id(1L,2L)).thenReturn(Optional.of(task));when(users.findByIdAndTenant_Id(3L,2L)).thenReturn(Optional.of(user));when(tasks.save(task)).thenReturn(task);assertSame(task,service.assign(1L,3L,2L));assertSame(user,task.getAssignedTo());}
 @Test void assignmentRejectsForeignOrMissingTask(){when(tasks.findByIdAndTenant_Id(1L,2L)).thenReturn(Optional.empty());assertThrows(ResourceNotFoundException.class,()->service.assign(1L,3L,2L));}
 @Test void assignmentRejectsForeignUser(){Tenant tenant=new Tenant("A");when(tasks.findByIdAndTenant_Id(1L,2L)).thenReturn(Optional.of(new Task("T","D",tenant)));when(users.findByIdAndTenant_Id(3L,2L)).thenReturn(Optional.empty());assertThrows(ResourceNotFoundException.class,()->service.assign(1L,3L,2L));}
 @Test void userCanUpdateAssignedTask(){Tenant tenant=new Tenant("A");Task task=new Task("T","D",tenant);when(tasks.findByIdAndTenant_IdAndAssignedTo_Id(1L,2L,3L)).thenReturn(Optional.of(task));when(tasks.save(task)).thenReturn(task);assertEquals(TaskStatus.DONE,service.updateStatus(1L,TaskStatus.DONE,2L,3L).getStatus());}
 @Test void userCannotUpdateUnassignedTask(){when(tasks.findByIdAndTenant_IdAndAssignedTo_Id(1L,2L,3L)).thenReturn(Optional.empty());assertThrows(ResourceNotFoundException.class,()->service.updateStatus(1L,TaskStatus.DONE,2L,3L));}
 @Test void adminGetsAllTenantTasks(){when(tasks.findAllByTenant_Id(2L)).thenReturn(List.of());assertTrue(service.list(2L,Role.ADMIN,3L).isEmpty());verify(tasks).findAllByTenant_Id(2L);}
 @Test void userGetsOnlyAssignedTasks(){when(tasks.findAllByTenant_IdAndAssignedTo_Id(2L,3L)).thenReturn(List.of());assertTrue(service.list(2L,Role.USER,3L).isEmpty());verify(tasks).findAllByTenant_IdAndAssignedTo_Id(2L,3L);}
}
